sys_script_include.script:
var TaskUtilsCS = Class.create();
TaskUtilsCS.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getTasksForEvent: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new TaskUtils().getTasksForEvent(_eventId));
    },

    isTaskOverdue: function() {
		var _taskId = this.getParameter('sysparm_taskId');
        return JSON.stringify(new TaskUtils().isTaskOverdue(_taskId));
    },

    getTaskDetailsById: function() {
		var _taskId = this.getParameter('sysparm_taskId');
        return JSON.stringify(new TaskUtils().getTaskDetailsById(_taskId));
    },

    getTasksByDueDate: function() {
		var _dueDate = this.getParameter('sysparm_dueDate');
        return JSON.stringify(new TaskUtils().getTasksByDueDate(_dueDate));
    },

    type: 'TaskUtilsCS'
});
